// Package registry is the contract version registry: every escrow version a service may trust,
// per chain. A version is an immutable escrow with its fulfillment proxies and signature domain.
// Versions are only ever added; a payment keeps the version it was created on for life.
//
// The data lives in chains/<caip2 with ':' as '_'>.json and is embedded, so a consumer reads
// exactly the registry of the protocol commit it pins. chains/ is generated by cmd/gen-chains from
// versions.json and the deployments files.
package registry

import (
	"embed"
	"encoding/json"
	"fmt"
	"io/fs"
	"path"
	"sort"
	"strconv"
	"strings"
)

//go:embed chains/*.json
var chainFiles embed.FS

// Signature names the signing domain a version verifies.
type Signature struct {
	EIP712Name       string `json:"eip712Name,omitempty"`
	EIP712Version    string `json:"eip712Version,omitempty"`
	SVMDomainVersion int    `json:"svmDomainVersion,omitempty"`
	// SVMMessage is the form a Solana signer signs for this version; "" is the raw 32 byte hash.
	SVMMessage string `json:"svmMessage,omitempty"`
	// StellarDomainVersion is the version byte every Stellar escrow digest commits to.
	StellarDomainVersion int `json:"stellarDomainVersion,omitempty"`
}

// Version is one deployed escrow version on one chain.
type Version struct {
	ID                 string    `json:"id"`
	Source             string    `json:"source"`
	Escrow             string    `json:"escrow"`
	FulfillmentProxies []string  `json:"fulfillmentProxies"`
	Permit2            string    `json:"permit2,omitempty"`
	Signature          Signature `json:"signature"`
	// UnrecordedFulfillmentProxies names proxies that are trusted but absent from Source, with why.
	UnrecordedFulfillmentProxies map[string]string `json:"unrecordedFulfillmentProxies,omitempty"`
}

// Chain is every version on one chain, oldest first.
type Chain struct {
	Chain    string    `json:"chain"`
	Name     string    `json:"name"`
	Mainnet  bool      `json:"mainnet"`
	Versions []Version `json:"versions"`
}

// Registry is the parsed registry, keyed by CAIP-2 chain id.
type Registry struct {
	chains map[string]Chain
	folded map[string]string // lower-cased chain id -> chain id
}

// Load parses the embedded registry and validates it.
func Load() (*Registry, error) {
	return load(chainFiles)
}

// LoadFS parses and validates the registry held under chains/ in files, such as an older commit's
// chain files.
func LoadFS(files fs.FS) (*Registry, error) {
	return load(files)
}

func load(files fs.FS) (*Registry, error) {
	entries, err := fs.ReadDir(files, "chains")
	if err != nil {
		return nil, err
	}
	r := &Registry{chains: map[string]Chain{}, folded: map[string]string{}}
	for _, e := range entries {
		raw, err := fs.ReadFile(files, path.Join("chains", e.Name()))
		if err != nil {
			return nil, err
		}
		var c Chain
		dec := json.NewDecoder(strings.NewReader(string(raw)))
		dec.DisallowUnknownFields()
		if err := dec.Decode(&c); err != nil {
			return nil, fmt.Errorf("registry %s: %w", e.Name(), err)
		}
		if want := strings.ReplaceAll(c.Chain, ":", "_") + ".json"; e.Name() != want {
			return nil, fmt.Errorf("registry %s: holds chain %q, want file %s", e.Name(), c.Chain, want)
		}
		if err := c.validate(); err != nil {
			return nil, fmt.Errorf("registry %s: %w", e.Name(), err)
		}
		if other, ok := r.folded[strings.ToLower(c.Chain)]; ok {
			return nil, fmt.Errorf("registry %s: chain %q differs from %q only in case", e.Name(), c.Chain, other)
		}
		r.chains[c.Chain] = c
		r.folded[strings.ToLower(c.Chain)] = c.Chain
	}
	return r, nil
}

func (c Chain) validate() error {
	if c.Chain == "" || c.Name == "" || len(c.Versions) == 0 {
		return fmt.Errorf("chain, name and at least one version are required")
	}
	ids := map[string]bool{}
	escrows := map[string]string{}
	prev := 0
	for _, v := range c.Versions {
		if v.ID == "" || v.Source == "" || v.Escrow == "" || len(v.FulfillmentProxies) == 0 {
			return fmt.Errorf("version %q: id, source, escrow and fulfillmentProxies are required", v.ID)
		}
		if ids[v.ID] {
			return fmt.Errorf("version id %q appears twice", v.ID)
		}
		ids[v.ID] = true
		// Oldest first: a v<N> id must be higher than the one before it.
		if n, err := strconv.Atoi(strings.TrimPrefix(v.ID, "v")); err == nil && strings.HasPrefix(v.ID, "v") {
			if n <= prev {
				return fmt.Errorf("version %q is listed after a newer one, but versions are oldest first", v.ID)
			}
			prev = n
		}
		key := normalize(c.Chain, v.Escrow)
		if other, ok := escrows[key]; ok {
			return fmt.Errorf("escrow %s is under both %q and %q", v.Escrow, other, v.ID)
		}
		escrows[key] = v.ID
		if err := v.Signature.validate(c.Chain); err != nil {
			return fmt.Errorf("version %q: %w", v.ID, err)
		}
		for p := range v.UnrecordedFulfillmentProxies {
			if !containsAddr(c.Chain, v.FulfillmentProxies, p) {
				return fmt.Errorf("version %q: unrecorded proxy %s is not in fulfillmentProxies", v.ID, p)
			}
		}
	}
	return nil
}

// validate requires the domain fields of the chain's VM and no others: EIP-712 name and version on
// EVM and Tron, the SVM domain version (one byte) and message scheme on Solana, the Stellar domain
// version (one byte) on Stellar.
func (s Signature) validate(caip2 string) error {
	if strings.HasPrefix(caip2, "stellar:") {
		if s.StellarDomainVersion <= 0 || s.EIP712Name != "" || s.EIP712Version != "" || s.SVMDomainVersion != 0 || s.SVMMessage != "" {
			return fmt.Errorf("a Stellar version needs stellarDomainVersion and no EIP-712 or SVM fields")
		}
		if s.StellarDomainVersion > 255 {
			return fmt.Errorf("stellarDomainVersion %d does not fit in one byte", s.StellarDomainVersion)
		}
		return nil
	}
	if s.StellarDomainVersion != 0 {
		return fmt.Errorf("stellarDomainVersion is for Stellar versions only")
	}
	if strings.HasPrefix(caip2, "solana:") {
		if s.SVMDomainVersion <= 0 || s.EIP712Name != "" || s.EIP712Version != "" {
			return fmt.Errorf("a Solana version needs svmDomainVersion and no EIP-712 fields")
		}
		if s.SVMDomainVersion > 255 {
			return fmt.Errorf("svmDomainVersion %d does not fit in one byte", s.SVMDomainVersion)
		}
		// Only the raw hash scheme exists today.
		if s.SVMMessage != "" {
			return fmt.Errorf("svmMessage %q is not a known message scheme", s.SVMMessage)
		}
		return nil
	}
	if s.EIP712Name == "" || s.EIP712Version == "" || s.SVMDomainVersion != 0 || s.SVMMessage != "" {
		return fmt.Errorf("an EVM or Tron version needs eip712Name and eip712Version and no svmDomainVersion or svmMessage")
	}
	return nil
}

// Chains returns every chain id in the registry, sorted.
func (r *Registry) Chains() []string {
	out := make([]string, 0, len(r.chains))
	for k := range r.chains {
		out = append(out, k)
	}
	sort.Strings(out)
	return out
}

// Chain returns the versions on one chain. The chain id matches regardless of case.
func (r *Registry) Chain(caip2 string) (Chain, bool) {
	c, ok := r.chains[r.folded[strings.ToLower(caip2)]]
	return c, ok
}

// Version returns one version by chain and id.
func (r *Registry) Version(caip2, id string) (Version, bool) {
	c, _ := r.Chain(caip2)
	for _, v := range c.Versions {
		if v.ID == id {
			return v, true
		}
	}
	return Version{}, false
}

// VersionOfEscrow returns the version whose escrow is addr. EVM addresses match regardless of
// case; Tron and Solana addresses must match exactly. ok is false for an escrow no version lists,
// and the zero Version then carries no scheme or domain, so callers must not read it.
func (r *Registry) VersionOfEscrow(caip2, addr string) (Version, bool) {
	c, _ := r.Chain(caip2)
	for _, v := range c.Versions {
		if normalize(c.Chain, v.Escrow) == normalize(c.Chain, addr) {
			return v, true
		}
	}
	return Version{}, false
}

// HasEscrow reports whether addr is the escrow of some version on the chain.
func (r *Registry) HasEscrow(caip2, addr string) bool {
	_, ok := r.VersionOfEscrow(caip2, addr)
	return ok
}

// HasProxy reports whether addr is a fulfillment proxy of some version on the chain.
func (r *Registry) HasProxy(caip2, addr string) bool {
	c, _ := r.Chain(caip2)
	for _, v := range c.Versions {
		if containsAddr(c.Chain, v.FulfillmentProxies, addr) {
			return true
		}
	}
	return false
}

// EnvList is an environment's version ids per chain: the versions new payments may name. It doesn't
// pick a default; each service keeps its configured escrow as the default.
type EnvList map[string][]string

// ParseEnvList parses "chain=id[,id];chain=id" as set in env-config.yaml.
func ParseEnvList(s string) (EnvList, error) {
	out := EnvList{}
	for _, part := range strings.Split(s, ";") {
		part = strings.TrimSpace(part)
		if part == "" {
			continue
		}
		i := strings.LastIndex(part, "=")
		if i <= 0 {
			return nil, fmt.Errorf("%q: want chain=id[,id]", part)
		}
		chain := strings.TrimSpace(part[:i])
		if chain == "" {
			return nil, fmt.Errorf("%q: want chain=id[,id]", part)
		}
		if _, dup := out[chain]; dup {
			return nil, fmt.Errorf("chain %s listed twice", chain)
		}
		var ids []string
		seen := map[string]bool{}
		for _, id := range strings.Split(part[i+1:], ",") {
			id = strings.TrimSpace(id)
			if id == "" {
				return nil, fmt.Errorf("chain %s: empty version id", chain)
			}
			if seen[id] {
				return nil, fmt.Errorf("chain %s: version id %s listed twice", chain, id)
			}
			seen[id] = true
			ids = append(ids, id)
		}
		out[chain] = ids
	}
	return out, nil
}

// CheckEnvList fails on a chain or version id the registry lacks.
func (r *Registry) CheckEnvList(l EnvList) error {
	for chain, ids := range l {
		if _, ok := r.chains[chain]; !ok {
			return fmt.Errorf("chain %s is not in the registry (chain ids are case sensitive)", chain)
		}
		for _, id := range ids {
			if _, ok := r.Version(chain, id); !ok {
				return fmt.Errorf("chain %s: version %s is not in the registry", chain, id)
			}
		}
	}
	return nil
}

// Allowed returns the registry versions l lists for the chain, in list order. The chain id
// matches regardless of case; l must have passed CheckEnvList.
func (r *Registry) Allowed(l EnvList, caip2 string) []Version {
	c, ok := r.Chain(caip2)
	if !ok {
		return nil
	}
	var out []Version
	for _, id := range l[c.Chain] {
		if v, ok := r.Version(c.Chain, id); ok {
			out = append(out, v)
		}
	}
	return out
}

// normalize folds case on EVM chains only; Tron and Solana addresses are case sensitive base58.
func normalize(caip2, addr string) string {
	addr = strings.TrimSpace(addr)
	if strings.HasPrefix(caip2, "eip155:") {
		return strings.ToLower(addr)
	}
	return addr
}

func containsAddr(caip2 string, list []string, addr string) bool {
	for _, a := range list {
		if normalize(caip2, a) == normalize(caip2, addr) {
			return true
		}
	}
	return false
}
